    private static readonly IReadOnlyDictionary<string, IReadOnlyDictionary<string, LocalizedDisplayText>> SubtopicDisplayTextByLanguageId = BuildSubtopicDisplayTextByLanguageId();

    public static string GetTitleTemplate(string languageId) => GetScreenText(languageId).TitleTemplate;

    public static string GetSubtitle(string languageId) => GetScreenText(languageId).Subtitle;

    public static string GetFreeConversationTitle(string languageId) => GetScreenText(languageId).FreeConversationTitle;

    public static string GetFreeConversationSubtitle(string languageId) => GetScreenText(languageId).FreeConversationSubtitle;

    public static IReadOnlyDictionary<string, LocalizedDisplayText> BuildSubtopicDisplayText(string languageId)
    {
        var normalizedLanguageId = InterfaceLanguageOptions.GetById(languageId).Id;
        return SubtopicDisplayTextByLanguageId.TryGetValue(normalizedLanguageId, out var localizedText)
            ? localizedText
            : SubtopicDisplayTextByLanguageId[InterfaceLanguageOptions.EnglishId];
    }

    private static SubtopicsScreenText GetScreenText(string languageId)
    {
        var normalizedLanguageId = InterfaceLanguageOptions.GetById(languageId).Id;
        return ScreenTextByLanguageId.TryGetValue(normalizedLanguageId, out var text) ? text : ScreenTextByLanguageId[InterfaceLanguageOptions.EnglishId];
    }

