    private static IReadOnlyDictionary<string, LocalizedDisplayText> Map(params (string Key, string Title, string Description)[] values)
    {
        return values.ToDictionary(value => value.Key, value => new LocalizedDisplayText(value.Title, value.Description), StringComparer.OrdinalIgnoreCase);
    }

